import { TypedEventBus } from "../../events/TypedEventBus";
import { TableIdentity, TableStats } from "./TableListTypes";

export interface TableListModelEvents {
    /** 一批身分/佔用資料到位（啟動拉取或加減桌推播後皆會發出，list 是本次變動的桌） */
    identitiesChanged: { tables: TableIdentity[] };
    /** 單桌統計資料更新（選中拉取或週期輪詢後） */
    statsChanged: { tableId: string; stats: TableStats };
    /** 桌位被移除（伺服器通知減桌） */
    tableRemoved: { tableId: string };
}

/**
 * TableListModel
 *
 * 只做「存資料 + 發事件」，不做 join／篩選／排序——那是 TableListViewModel
 * （快取篩選層）的職責，見 docs/worklist-EN.md「桌列表」一節的骨架設計。
 * 身分（identities）跟統計（stats）用 tableId 當 key 分開存放兩個 Map，
 * 對應舊專案 GameTableInfoVO／TableStatisticalDisplayInfo 拆兩個平行記錄的設計。
 */
export class TableListModel {
    readonly events = new TypedEventBus<TableListModelEvents>();

    private readonly identities = new Map<string, TableIdentity>();
    private readonly stats = new Map<string, TableStats>();

    /** 新增或覆蓋一批桌位身分資料（啟動拉取／加桌推播共用） */
    upsertIdentities(tables: TableIdentity[]): void {
        for (const table of tables) this.identities.set(table.tableId, table);
        this.events.emit("identitiesChanged", { tables });
    }

    /** 移除桌位（減桌推播） */
    removeTables(tableIds: string[]): void {
        for (const tableId of tableIds) {
            this.identities.delete(tableId);
            this.stats.delete(tableId);
            this.events.emit("tableRemoved", { tableId });
        }
    }

    /** 更新單桌統計資料（選中拉取／輪詢共用） */
    upsertStats(tableId: string, stats: TableStats): void {
        this.stats.set(tableId, stats);
        this.events.emit("statsChanged", { tableId, stats });
    }

    getIdentity(tableId: string): TableIdentity | undefined {
        return this.identities.get(tableId);
    }

    getStats(tableId: string): TableStats | undefined {
        return this.stats.get(tableId);
    }

    getAllIdentities(): TableIdentity[] {
        return Array.from(this.identities.values());
    }
}
