import { _decorator, Node, Layout, Button, Label, Sprite, SpriteFrame, UIOpacity, Vec3, tween, EffectAsset, Material, Tween, sp } from 'cc';
import TemplateViewModel from './TemplateViewModel';
import StoreManager from '../../store/StoreManager';
import AppAssetBundle from '../../utils/AppAssetBundle';
import GameConfigManager from '../../config/GameConfigManager';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';
import type { GameStateKey } from '../../states/GameStateKey';
import { BaseButton } from '../BaseButton/BaseButton';
const { ccclass, property } = _decorator;

@ccclass('1002/TemplateView_1002')
export class TemplateView extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供 TemplateViewModel 呼叫 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(bus: TypedEventBus<TEvents>, type: K, handler: (payload: TEvents[K]) => void): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Layout)
    betFrame: Layout = null;
    @property(Layout)
    winFrame: Layout = null;
    @property(Layout)
    userFrame: Layout = null;
    @property(Layout)
    spinFrame: Layout = null;
    @property(Layout)
    lockView: Layout = null;

    @property(Button)
    spinBtn: Button = null;
    @property(Button)
    autoBtn: Button = null;
    @property(BaseButton)
    turboBtn: BaseButton = null;
    @property(BaseButton)
    minusBtn: BaseButton = null;
    @property(BaseButton)
    plusBtn: BaseButton = null;
    @property(BaseButton)
    selectBetBtn: BaseButton = null;

    //spriteFrame
    @property(Node)
    spinArrowSprite: Node = null;
    @property(Node)
    spinStopSprite: Node = null;
    @property(Node)
    autoArrowSprite: Node = null;
    @property(Node)
    autoSpinStatus: Node = null;
    @property(Node)
    shopBtn: Node = null;

    @property(sp.Skeleton)
    spinBtnSpine: sp.Skeleton = null;

    @property(Label)
    versionLabel: Label = null;

    public isPrimary: boolean = false;

    viewModel: TemplateViewModel;
    private spinTween: any;
    private spinSweepTween: Tween<{ p: number }> | null = null;
    assetBundle: AppAssetBundle;

    protected override start(): void {}

    /** 保留 FG 狀態同步介面；1002 目前沒有局數倒數 UI。 */
    updateFgRound(_remaining: number, _total: number, _awarded: number = 0): void {}

    /** 保留 FG 模式同步介面；1002 目前不切換 TemplateView 顯示。 */
    setGameMode(_gameMode: GameStateKey): void {}

    protected override onLoad(): void {
        this.assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        this.viewModel = new TemplateViewModel(this);
        this.viewModel.initial();
        this.setupSpinSweep();
        this.spinBtnSpine?.clearTracks();
        this.assetBundle.getSpriteFrame('main_btn_pause').then((frame) => {
            this.pauseIconSpriteFrame = frame;
        });
    }

    private async setupSpinSweep(): Promise<void> {
        try {
            const sprite = this.spinArrowSprite?.getComponent(Sprite);
            if (!sprite) {
                console.warn('[sweep] spinArrowSprite has no Sprite component');
                return;
            }

            const bundle = await this.assetBundle.loadBundle();
            const effect = await new Promise<EffectAsset>((resolve, reject) => {
                bundle.load('resources/shaders/sprite-sweep', EffectAsset, (err, asset) => {
                    if (err) reject(err);
                    else resolve(asset as EffectAsset);
                });
            });

            const material = new Material();
            material.initialize({ effectAsset: effect });
            sprite.customMaterial = material;

            const matInstance = sprite.getMaterialInstance(0);
            if (!matInstance) return;

            const state = { p: 0 };
            this.spinSweepTween = tween(state)
                .repeatForever(
                    tween(state)
                        .set({ p: 0 })
                        .to(
                            1.0,
                            { p: 1.0 },
                            {
                                easing: 'cubicOut',
                                onUpdate: () => matInstance.setProperty('sweepProgress', state.p),
                            }
                        )
                        .delay(1.5)
                )
                .start();
        } catch (e) {
            console.warn('[sweep] caught:', e);
        }
    }

    override onDestroy(): void {
        if (this.spinSweepTween) {
            this.spinSweepTween.stop();
            this.spinSweepTween = null;
        }
        super.onDestroy();
    }

    // ******************** Button Click  ************************
    spinClick() {
        this.playSpinBtnSpine();
        this.viewModel.spinClick();
    }

    private playSpinBtnSpine(): void {
        if (!this.spinBtnSpine) return;
        this.spinBtnSpine.setAnimation(0, 'animation', false);
    }
    menuClick() {
        this.viewModel.menuClick();
    }
    autoClick() {
        this.viewModel.autoClick();
    }
    turboClick() {
        this.viewModel.turboClick();
    }
    minusClick() {
        this.viewModel.minusClick();
    }
    plusClick() {
        this.viewModel.plusClick();
    }

    selectBetClick() {
        this.viewModel.selectBetClick();
    }

    storeClick() {
        this.viewModel.storeClick();
    }

    // ******************** 更新 UI  ************************
    updateAutoSpinTimes(times) {
        this.autoSpinStatus.getChildByName('AutoTimes').getComponent(Label).string = `${times}`;
    }

    updateUserBalance(balance) {
        let userBalance = this.userFrame.node.getChildByName('UserBalance').getComponent(Label);
        userBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    updateWinBalance(balance) {
        // console.log("updateWinBalance balance = ", balance);

        let winBalance = this.winFrame.node.getChildByName('WinBalance').getComponent(Label);
        winBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    updateBetBalance(balance) {
        let betBalance = this.betFrame.node.getChildByName('BetBalance').getComponent(Label);
        betBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    // ******************** 更新 UI  ************************
    /**
     * 切換加速鈕的檔位 圖由 BaseButton 的型態列表決定
     *
     * @param gear TURBOSTATUSMAP 的其中一個值
     */
    setTurboGear(gear: string): void {
        if (!this.turboBtn?.node?.isValid) return;
        this.turboBtn.setVariant(gear);
    }
    /**
     * 一次設定三顆注額按鈕能不能按，不能按的狀態由 BaseButton 負責顯示。
     *
     * @param minus 減注額按鈕。
     * @param plus 加注額按鈕。
     * @param select 選注額按鈕。
     */
    setBetButtons(minus: boolean, plus: boolean, select: boolean) {
        this.minusBtn.setInteractable(minus);
        this.plusBtn.setInteractable(plus);
        this.selectBetBtn.setInteractable(select);
    }
    /**
     * 依目前注額重新整理三顆注額按鈕。
     *
     * @param locked 是否鎖住，轉動中為 true。
     */
    refreshBetButtons(locked: boolean) {
        this.viewModel.refreshBetButtons(locked);
    }
    // ******************** 設定狀態  ************************
    setSpinArrowStatus(status: boolean) {
        this.spinArrowSprite.active = status;
    }

    setSpinStopStatus(status: boolean) {
        this.spinStopSprite.active = status;
    }

    setSpinFrameVisible(status: boolean) {
        this.spinFrame.node.active = status;
    }
    setBetFrameVisible(status: boolean) {
        this.betFrame.node.active = status;
    }
    setInfiniteVisible(status: boolean) {
        this.autoSpinStatus.getChildByName('Infinite').active = status;
        this.autoSpinStatus.getChildByName('AutoTimes').active = !status;
    }
    setVersionLabel(version: string) {
        this.versionLabel.string = version;
    }
    setAutoSpinStatus(status: boolean) {
        this.autoSpinStatus.active = status;
    }

    setDefaultMode() {
        //Layout
        this.setSpinFrameVisible(true);
        this.setBetFrameVisible(true);
        //個別按鈕
        this.setSpinArrowStatus(true);
        this.resumeSpinAction();
        this.setSpinStopStatus(false);
        this.setAutoSpinStatus(false);
        this.setInfiniteVisible(false);
        this.stopAutoSpinAction();
    }
    setSpinMode() {
        //Layout
        this.setSpinFrameVisible(true);
        this.setBetFrameVisible(true);
        this.playSpinAction(() => {
            //個別按鈕
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(true);
            this.setAutoSpinStatus(false);
            this.setInfiniteVisible(false);
        });
    }
    setAutoSpinMode(times?: number | string) {
        this.playSpinAction(() => {
            this.playAutoSpinAction(times);
            //Layout
            this.setSpinFrameVisible(true);
            this.setBetFrameVisible(true);
            //個別按鈕
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(true);
        });
    }

    setFeatureMode() {
        //Layout
        this.setSpinFrameVisible(false);
        this.setBetFrameVisible(false);
    }

    //spin 動畫
    playSpinAction(callBack?: Function) {
        if (this.spinTween) {
            if (callBack) callBack();
            return;
        }

        let uiOpacity = this.spinArrowSprite.getComponent(UIOpacity) || this.spinArrowSprite.addComponent(UIOpacity);
        this.spinTween = tween(this.spinArrowSprite)
            .parallel(
                tween()
                    .to(1, { eulerAngles: new Vec3(0, 0, -360) }, { easing: 'backIn' })
                    .call(() => {
                        this.setSpinArrowStatus(false);
                    }),
                tween(uiOpacity).delay(0.8).to(0.2, { opacity: 0 }, { easing: 'sineOut' }),
                tween()
                    .delay(0.9)
                    .call(() => {
                        if (callBack) callBack();
                    })
            )
            .start();
    }
    resumeSpinAction() {
        // console.log("resumeSpinAction");
        if (this.spinTween) {
            this.spinTween.stop();
            this.spinTween = null;
        }
        this.spinArrowSprite.eulerAngles = new Vec3(0, 0, 0);
        let uiOpacity = this.spinArrowSprite.getComponent(UIOpacity) || this.spinArrowSprite.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
    }

    // autoSpin 動畫
    private pauseIcon: Node | null = null;
    private pauseIconSpriteFrame: SpriteFrame | null = null;

    private async ensurePauseIcon(): Promise<Node> {
        if (this.pauseIcon?.isValid) return this.pauseIcon;
        const node = new Node('pauseIcon');
        this.pauseIcon = node;
        node.layer = this.autoArrowSprite.layer;
        this.autoArrowSprite.parent.addChild(node);
        const frame = this.pauseIconSpriteFrame ?? (await this.assetBundle.getSpriteFrame('main_btn_pause'));
        if (node.isValid) node.addComponent(Sprite).spriteFrame = frame;
        return node;
    }

    async playAutoSpinAction(_speed?: number | string): Promise<void> {
        (await this.ensurePauseIcon()).active = true;
    }
    async stopAutoSpinAction(): Promise<void> {
        if (this.pauseIcon?.isValid) this.pauseIcon.active = false;
        this.autoArrowSprite.active = false;
    }
    setLockStatus(islock) {
        this.lockView.node.active = islock;
    }
}
