import { _decorator, Component, view, Vec3, screen } from "cc";

const { ccclass, property } = _decorator;

/**
 * 掛在 3D 粒子的父節點上。
 * 根據螢幕實際大小 vs 設計解析度的縮放比例，調整節點 scale，
 * 讓 3D 粒子跟 2D UI 的 Canvas 縮放一致。
 */
@ccclass("1002/CameraSync3D")
export class CameraSync3D extends Component {

    private baseScale: Vec3 = new Vec3(1, 1, 1);

    protected override onLoad(): void {
        this.baseScale = this.node.scale.clone();
        this.sync();
        view.on("canvas-resize", this.sync, this);
    }

    private sync(): void {
        // Canvas SHOW_ALL: scale = min(screenW/designW, screenH/designH)
        const designW = 1280;
        const designH = 720;
        const dpr = screen.devicePixelRatio;
        const screenW = screen.windowSize.width / dpr;
        const screenH = screen.windowSize.height / dpr;
        const scaleX = screenW / designW;
        const scaleY = screenH / designH;
        const canvasScale = Math.min(scaleX, scaleY);

        // 3D camera 是 full viewport，不受 Canvas 縮放
        // 補償：粒子 scale = canvasScale / max(scaleX, scaleY)
        const ratio = canvasScale / Math.max(scaleX, scaleY);
        this.node.setScale(
            this.baseScale.x * ratio,
            this.baseScale.y * ratio,
            this.baseScale.z
        );
    }

    protected override onDestroy(): void {
        view.off("canvas-resize", this.sync, this);
    }
}
