    protected override gameInit(): void {
        this.initSharedControllers();
        this.storeManager = StoreManager.getInstance();
        this.registerBeforeExitHook();
        AppAudio.getInstance().preloadAll(Object.values(EFFECTSMAP));
        this.sceneSpeedUnsubscribe = SceneSpeedStore.subscribe(GameConfigManager.GAMEID, (config) => this.onSceneSpeedChanged(config));
        this.loadReelConfig();
        installDirectorSpeedHook();

        // 狀態機（比照舊專案 GameMain.InitStates()）：註冊 NG/FG 兩個狀態，預設進入 NG
        this.registerState(GameStateKey.NG, new NGState_1002());
        this.registerState(GameStateKey.FG, new FGState_1002());
        this.changeState(GameStateKey.NG);

        // 每個 view 各自建立 model — reelCount 從 prefab 的 reelViews.length 動態取
        this.forEachView((v) => {
            const sm = new SlotMachineModel({ reelCount: v.slotMachineView.reelViews.length });
            sm.initReelModels();
            this.registerSlotMachineModel(sm);
            v.slotMachineView.init(sm);
            v.slotMachineModel = sm;
        });

        // viewH 的 model 作為向下相容欄位
        this.slotMachineModel = this.viewH.slotMachineModel;

        this.spinShortcut.bind();

        this.buyFeature.bindButtons();
        // buy feature 價格/閃爍的事件訂閱（BET_BALANCE_CHANGED/USER_BALANCE_CHANGED/GAME_SPIN_DATA_CHANGED/GAME_INIT_EXTRA_CHANGED）
        // 都搬進 BuyFeatureController 自己管理，兩邊遊戲不用再各自重複接線
        this.buyFeature.bindEvents(gameRuntimeEventBus, this.subscriptions);

        this.bindExtraBet();

        // 把彈窗提升到場景根節點最上層，蓋住 TemplateView
        this.reparentPopups();

        this.mainCamera = director.getScene()?.getChildByName('Canvas')?.getChildByName('Camera')?.getComponent(Camera) ?? null;

        // 直橫版切換：透過 layer 過濾，讓非當前方向的子樹完全不被 camera 渲染
        const device = StoreManager.getInstance().getDeviceStore();
        this.orientation.init(device.isLandscape);
        // [EVT-GAME-008] 裝置直橫版切換改由 EventBus 觸發
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.orientation.applyOrientation(device.isLandscape);
        });

        // 這裡原本每次 stateChanged 都把所有符號 spine 的 timeScale 設成 0（"凍住 idle 動畫"）。
        // 移除原因有兩層：
        //   1. 它一直是空轉的——走的 SlotMachineView.setSymbolSpinesTimeScale() 讀的是
        //      ReelView_1002.symbolSpines，那個陣列從宣告到刪除為止沒有任何地方 push 過。
        //   2. 改成物件池之後也不需要了。沒被租用的狀態其顯示物件是關著的，
        //      sp.Skeleton.update() 只看元件 enabled 與節點 active，關著就不吃每幀 CPU；
        //      活著的 spine 剛好就是當下狀態需要的那一支。
        // 真接上去反而會凍住 scatter 的 idle 循環。

        this.initReactions();
    }

    /** 綁定每個 view 的加注開關，並訂閱加注變動事件。 */
    private bindExtraBet(): void {
        this.forEachView((v) => {
            if (!v.extraBetToggle) {
                console.warn(`[ExtraBet] ${v.node.name} 沒有綁定 extraBetToggle`);
                return;
            }
            v.extraBetToggle.onToggleOn = (isON: boolean) => this.onExtraBetToggle(isON);
        });
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.EXTRA_BET_CHANGED, () => this.refreshExtraBet());
        this.refreshExtraBet();
    }

    /** 判斷現在能不能切換加注。 */
    private canToggleExtraBet(): boolean {
        const store = this.storeManager.getGameStore();
        const buyPending = this.buyFeature.pendingBuyFeatureId != null || store.buyFeatureData != null;
        return store.canToggleExtraBet(this.slotMachineModel.state === SlotMachineState.IDLE, buyPending);
    }

    /**
     * 加注開關被點擊：可切換時寫入 GameStore，最後依 GameStore 同步畫面。
     *
     * @param isON 開關被點成的狀態。
     */
    private onExtraBetToggle(isON: boolean): void {
        if (this.extraBetSyncing) return;
        if (this.canToggleExtraBet()) this.storeManager.getGameStore().setExtraBetEnabled(isON);
        // 依 model 同步開關
        this.refreshExtraBet();
    }

    /** 依 GameStore 同步各 view 的加注顯示。 */
    private refreshExtraBet(): void {
        const store = this.storeManager.getGameStore();
        const state = { available: store.extraBetTier != null, enabled: store.extraBetEnabled };
        this.extraBetSyncing = true;
        this.forEachView((v) => v.applyExtraBet(state));
        this.extraBetSyncing = false;
    }

    /** 進入遊戲：啟動音樂、背景與 UI 呈現（比照舊專案 SGEngine GameMain 的 doEnterGame()/onEnterGame()） */
    protected override enterGame(): void {
        this.popups.preloadAll();
        this.popups.preloadTransition();

        this.applyBackgroundMode(false);
        this.initCharacterIdle();
        this.applyGameModeUi(false);
        // collect / transition spine 預設關（prefab 可能留 active），只在播放時開
        this.forEachView((v) => {
            if (v.collectSkel) v.collectSkel.node.active = false;
            if (v.transitionSkel) v.transitionSkel.node.active = false;
        });
        this.resetWinBar();
    }

    private static readonly FG_TRIGGER_SCATTERS = 4;

    /** 讀取轉輪節奏＋整體 scene 加速倍率的本地端預設值（共用同一份 jsons/reelConfig.json），
     *  分別設進 ReelTimingDebugStore／SceneSpeedStore 的 local default 層——PM 透過 DebugPanel
     *  存的 localStorage 覆寫值優先權還是更高 */
    private async loadReelConfig(): Promise<void> {
        try {
            const asset = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadAsset(REEL_CONFIG_PATH, JsonAsset);
            ReelTimingDebugStore.setLocalDefault(GameConfigManager.GAMEID, parseReelConfig(asset.json));
            SceneSpeedStore.setLocalDefault(GameConfigManager.GAMEID, parseSceneSpeedConfig(asset.json));
        } catch (error) {
            console.warn('[GameMain_1002] 讀取 reelConfig.json 失敗，沿用 Editor 基準值', error);
        }
    }

    /** public：供 Net/SpinResultHandler 呼叫 — 顯示 free_board 彈窗，關閉後 resolve */
