    /**
     * 播放轉場 煙花蓋滿畫面時才切換背景與免費遊戲介面
     *
     * @param direction 進入或離開
     * @returns 轉場結束時完成
     */
    public playTransition(direction: TransitionDirection): Promise<void> {
        const toFree = direction === 'enter';
        AppAudio.getInstance().playEffect(EFFECTSMAP.TRANSITION);
        this.scheduleOnce(() => {
            this.applyBackgroundMode(toFree);
            this.applyGameModeUi(toFree);
        }, TRANSITION_COVER_SEC);
        return this.popups.playTransition();
    }

